// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with 2 or more lines get an extra 5% bulk discount, applied after the
// customer's discount. `bulkMinLines` is the number of lines the bulk discount
// starts from; wholesale invoices pass their own (see invoice.js).
export function total(items, discount = 0, { bulkMinLines = 2 } = {}) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
